(()=>{
'use strict';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateText=v=>String(v||'').slice(0,10);
const timeText=v=>{if(!v)return'-';const d=new Date(v);return Number.isNaN(d.getTime())?'-':d.toLocaleTimeString('ko-KR',{timeZone:'Asia/Seoul',hour:'2-digit',minute:'2-digit',hour12:false})};
const titleKey=v=>String(v||'').replace(/\s+/g,'').toLowerCase();
const isCeo=x=>['대표','대표이사','ceo','chiefexecutiveofficer'].includes(titleKey(x?.title||x?.employee_title));
const statusText=s=>({WORKING:'근무중',DONE:'퇴근완료',ABSENT:'미출근',LEAVE:'휴가',STATUTORY:'법정휴가'}[s]||s||'-');
const leaveTypeText=t=>({annual:'연차',am_half:'오전반차',pm_half:'오후반차',statutory:'법정휴가'}[t]||t||'-');
const leaveStatusText=s=>({PENDING_1:'승인대기',PENDING_2:'승인대기',APPROVED:'승인',REJECTED:'반려',CANCELLED:'취소'}[s]||s||'-');
async function api(url){const r=await fetch(url,{credentials:'same-origin',cache:'no-store'});const p=await r.json().catch(()=>({success:false,message:'서버 응답 오류'}));if(!r.ok||p?.success===false)throw new Error(p?.message||'불러오지 못했습니다.');return p?.data??p}
function statutoryOnDate(leaves,name,selectedDate){return (leaves||[]).some(l=>l.leave_type==='statutory'&&l.status==='APPROVED'&&String(l.employee_name||'')===String(name||'')&&dateText(l.start_date)<=selectedDate&&dateText(l.end_date)>=selectedDate)}
function normalize(raw){const date=String(raw?.date||'');const leaves=(raw?.leaves||[]).filter(x=>!isCeo(x));const employees=(raw?.employees||[]).filter(x=>!isCeo(x)).map(x=>{const statutory=x.currentLeaveType==='statutory'||statutoryOnDate(leaves,x.name,date);return statutory?{...x,attendanceStatus:'STATUTORY',currentLeaveType:'statutory'}:x});const summary={total:employees.length,checkedIn:employees.filter(x=>['WORKING','DONE'].includes(x.attendanceStatus)).length,working:employees.filter(x=>x.attendanceStatus==='WORKING').length,onLeave:employees.filter(x=>x.attendanceStatus==='LEAVE').length,statutory:employees.filter(x=>x.attendanceStatus==='STATUTORY').length,absent:employees.filter(x=>x.attendanceStatus==='ABSENT').length};const departments=[...new Set(employees.map(x=>String(x.department||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'ko'));return{...raw,employees,leaves,summary,departments}}
function ensureStatutoryOption(){const s=document.getElementById('leaveType');if(!s||s.querySelector('option[value="statutory"]'))return;const o=document.createElement('option');o.value='statutory';o.textContent='법정휴가';s.appendChild(o)}
function css(){if(document.getElementById('namoAdminTableStyle'))return;const s=document.createElement('style');s.id='namoAdminTableStyle';s.textContent=`
.ao-entry{margin-top:10px;border:1px solid #cbd8e0!important;background:linear-gradient(135deg,#0f3550,#174f72)!important;color:#fff!important}
.nat-wrap{padding:0 0 84px}.nat-head{background:linear-gradient(135deg,#10354f,#165a7e);color:#fff;border-radius:14px;padding:10px 11px;margin-bottom:7px}.nat-headline{display:flex;align-items:center;gap:8px}.nat-back{border:0;background:rgba(255,255,255,.14);color:#fff;border-radius:8px;padding:6px 8px;font-size:12px;font-weight:900}.nat-title{font-size:17px;font-weight:950;letter-spacing:-.3px}.nat-desc{margin:4px 0 0;font-size:9.5px;color:#cfe0ea}.nat-dates{display:grid;grid-template-columns:1fr 1fr;gap:5px;margin-top:7px}.nat-dates input{height:31px;min-width:0;border:1px solid rgba(255,255,255,.45);border-radius:7px;padding:0 7px;background:#fff;color:#17364d;font-size:11px;font-weight:800}
.nat-kpis{display:grid;grid-template-columns:repeat(6,minmax(55px,1fr));gap:3px;margin:6px 0;overflow-x:auto}.nat-kpi{background:#fff;border:1px solid #d9e3ea;border-radius:8px;padding:5px 6px;min-width:55px}.nat-kpi span{display:block;color:#718391;font-size:8px;font-weight:800;white-space:nowrap}.nat-kpi b{display:block;margin-top:1px;color:#163b56;font-size:15px;line-height:1.1}.nat-kpi.green b{color:#0a8c53}.nat-kpi.blue b{color:#1974d2}.nat-kpi.orange b{color:#e26c0b}.nat-kpi.purple b{color:#7547c8}.nat-kpi.red b{color:#d92d20}
.nat-tools{display:grid;grid-template-columns:1fr 104px 96px;gap:4px;margin:6px 0}.nat-tools input,.nat-tools select{height:31px;min-width:0;border:1px solid #ccd9e1;border-radius:7px;background:#fff;padding:0 7px;font-size:10.5px;color:#263f51}.nat-tabs{display:flex;gap:4px;margin:5px 0}.nat-tab{height:29px;border:1px solid #cad8e1;background:#fff;color:#456071;padding:0 10px;border-radius:999px;font-size:10px;font-weight:900}.nat-tab.on{background:#174f72;border-color:#174f72;color:#fff}.nat-count{margin:4px 1px;font-size:10px;font-weight:900;color:#29485f}
.nat-table-wrap{overflow:auto;background:#fff;border:1px solid #d8e3ea;border-radius:9px;-webkit-overflow-scrolling:touch}.nat-table{width:100%;min-width:710px;border-collapse:collapse;table-layout:fixed;font-size:9.5px}.nat-table th{position:sticky;top:0;z-index:2;background:#eaf1f6;color:#344f63;font-weight:950;padding:6px 3px;border-right:1px solid #dce5eb;border-bottom:1px solid #cfdbe4;white-space:nowrap}.nat-table td{height:31px;padding:4px 3px;border-right:1px solid #edf1f4;border-bottom:1px solid #e7edf1;text-align:center;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.nat-table tr:last-child td{border-bottom:0}.nat-table .nat-no{width:30px}.nat-table .nat-name{width:82px;text-align:left;font-weight:900;color:#123d59}.nat-table .nat-dept{width:64px}.nat-table .nat-status{width:67px}.nat-table .nat-time{width:49px}.nat-table .nat-month{width:48px}.nat-table .nat-leave{width:47px}.nat-pill{display:inline-flex;align-items:center;justify-content:center;min-width:45px;border-radius:999px;padding:3px 5px;font-size:8.5px;font-weight:950;background:#f0f2f4;color:#66727a}.nat-pill.WORKING{background:#e6f7ee;color:#087443}.nat-pill.DONE{background:#eaf2ff;color:#245bc2}.nat-pill.LEAVE{background:#fff2dc;color:#9a6500}.nat-pill.STATUTORY{background:#efe9ff;color:#6d3fc2}.nat-pill.ABSENT{background:#fff0ef;color:#c42b22}
.nat-leave-list{display:grid;gap:5px}.nat-leave-row{background:#fff;border:1px solid #dbe5eb;border-radius:8px;padding:8px}.nat-leave-top{display:flex;align-items:center;justify-content:space-between;gap:7px}.nat-leave-name{font-size:11px;font-weight:950;color:#17364d}.nat-leave-sub{font-size:9px;color:#72838f;margin-top:2px}.nat-leave-meta{font-size:9.5px;color:#415a6c;margin-top:5px}.nat-empty{text-align:center;padding:22px 8px;color:#82939f;font-size:11px}
@media(max-width:430px){.nat-tools{grid-template-columns:1fr 92px}.nat-tools select:last-child{grid-column:1/-1}.nat-kpis{grid-template-columns:repeat(6,58px)}.nat-title{font-size:16px}}
`;document.head.appendChild(s)}
let data=null,tab='attendance';
function install(){css();ensureStatutoryOption();const card=document.getElementById('adminCard');if(!card)return;let b=document.getElementById('adminOverviewOpen');if(!b){b=document.createElement('button');b.id='adminOverviewOpen';b.className='soft full ao-entry';b.type='button';card.appendChild(b)}b.textContent='전체 직원 근태 · 연차 현황';b.onclick=open}
async function open(){let page=document.getElementById('pageAdminOverview');if(!page){page=document.createElement('section');page.id='pageAdminOverview';page.className='page';(document.querySelector('#mainApp main')||document.getElementById('mainApp')).appendChild(page)}document.querySelectorAll('.page').forEach(x=>x.classList.add('hidden'));page.classList.remove('hidden');page.innerHTML='<div class="nat-wrap"><div class="nat-head"><div class="nat-headline"><button class="nat-back" id="natBack">‹ 홈</button><div class="nat-title">전사 근태 · 연차 현황</div></div><div class="nat-desc">관리자 전용 · 전체 직원 근태와 법정휴가 포함 · 대표이사 제외</div></div><div class="nat-empty">현황을 불러오는 중...</div></div>';document.getElementById('natBack').onclick=back;await load()}
function back(){document.getElementById('pageAdminOverview')?.classList.add('hidden');document.getElementById('pageHome')?.classList.remove('hidden');window.scrollTo({top:0,behavior:'auto'})}
async function load(){const p=document.getElementById('pageAdminOverview');try{const ds=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()),ms=ds.slice(0,7);data=normalize(await api(`/api/attendance/admin/overview?date=${encodeURIComponent(ds)}&month=${encodeURIComponent(ms)}`));render()}catch(e){p.innerHTML=`<div class="nat-wrap"><div class="nat-head"><div class="nat-headline"><button class="nat-back" id="natBack">‹ 홈</button><div class="nat-title">전사 근태 · 연차 현황</div></div></div><div class="nat-empty">${esc(e.message)}</div></div>`;document.getElementById('natBack').onclick=back}}
function render(){const p=document.getElementById('pageAdminOverview'),s=data.summary||{};p.innerHTML=`<div class="nat-wrap"><div class="nat-head"><div class="nat-headline"><button class="nat-back" id="natBack">‹ 홈</button><div class="nat-title">전사 근태 · 연차 현황</div></div><div class="nat-desc">관리자 전용 · 전체 직원 근태와 법정휴가 포함 · 대표이사 제외</div><div class="nat-dates"><input id="natDate" type="date" value="${esc(data.date)}"><input id="natMonth" type="month" value="${esc(data.month)}"></div></div><div class="nat-kpis"><div class="nat-kpi"><span>전체</span><b>${s.total||0}</b></div><div class="nat-kpi green"><span>출근</span><b>${s.checkedIn||0}</b></div><div class="nat-kpi blue"><span>근무중</span><b>${s.working||0}</b></div><div class="nat-kpi orange"><span>휴가</span><b>${s.onLeave||0}</b></div><div class="nat-kpi purple"><span>법정휴가</span><b>${s.statutory||0}</b></div><div class="nat-kpi red"><span>미출근</span><b>${s.absent||0}</b></div></div><div class="nat-tabs"><button class="nat-tab ${tab==='attendance'?'on':''}" data-nat-tab="attendance">전체 근태</button><button class="nat-tab ${tab==='leave'?'on':''}" data-nat-tab="leave">휴가 현황</button></div><div class="nat-tools"><input id="natQuery" placeholder="이름 · 부서 검색"><select id="natDept"><option value="">전체 부서</option>${(data.departments||[]).map(x=>`<option>${esc(x)}</option>`).join('')}</select><select id="natStatus"><option value="">전체 상태</option><option value="DONE">퇴근완료</option><option value="WORKING">근무중</option><option value="LEAVE">휴가</option><option value="STATUTORY">법정휴가</option><option value="ABSENT">미출근</option></select></div><div id="natList"></div></div>`;document.getElementById('natBack').onclick=back;document.querySelectorAll('[data-nat-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.natTab;render()});document.getElementById('natDate').onchange=reload;document.getElementById('natMonth').onchange=reload;document.getElementById('natQuery').oninput=renderList;document.getElementById('natDept').onchange=renderList;document.getElementById('natStatus').onchange=renderList;renderList()}
async function reload(){const d=document.getElementById('natDate').value,m=document.getElementById('natMonth').value;try{data=normalize(await api(`/api/attendance/admin/overview?date=${encodeURIComponent(d)}&month=${encodeURIComponent(m)}`));render()}catch(e){alert(e.message)}}
function renderList(){const box=document.getElementById('natList');if(!box)return;const q=(document.getElementById('natQuery')?.value||'').trim().toLowerCase(),dept=document.getElementById('natDept')?.value||'',status=document.getElementById('natStatus')?.value||'';if(tab==='attendance'){const rows=(data.employees||[]).filter(x=>(!dept||x.department===dept)&&(!status||x.attendanceStatus===status)&&(!q||`${x.name} ${x.department} ${x.title}`.toLowerCase().includes(q)));box.innerHTML=`<div class="nat-count">직원 ${rows.length}명 · 전체 행 표시</div><div class="nat-table-wrap"><table class="nat-table"><thead><tr><th class="nat-no">No</th><th class="nat-name">이름</th><th class="nat-dept">부서</th><th class="nat-status">상태</th><th class="nat-time">출근</th><th class="nat-time">퇴근</th><th class="nat-month">월근무</th><th class="nat-leave">연차</th><th class="nat-leave">사용</th><th class="nat-leave">잔여</th></tr></thead><tbody>${rows.map((x,i)=>`<tr><td>${i+1}</td><td class="nat-name" title="${esc(x.name)} ${esc(x.title||'')}">${esc(x.name)} ${esc(x.title||'')}</td><td>${esc(x.department||'-')}</td><td><span class="nat-pill ${esc(x.attendanceStatus)}">${esc(statusText(x.attendanceStatus))}</span></td><td>${esc(timeText(x.clockIn))}</td><td>${esc(timeText(x.clockOut))}</td><td>${Number(x.monthDays||0)}일</td><td>${Number(x.leaveGranted||0)}</td><td>${Number(x.leaveUsed||0)}</td><td>${Number(x.leaveRemaining||0)}</td></tr>`).join('')}</tbody></table></div>`}else{const rows=(data.leaves||[]).filter(x=>(!dept||x.employee_department===dept)&&(!q||`${x.employee_name} ${x.employee_department} ${x.employee_title}`.toLowerCase().includes(q)));box.innerHTML=`<div class="nat-count">휴가 내역 ${rows.length}건</div><div class="nat-leave-list">${rows.length?rows.map(x=>`<div class="nat-leave-row"><div class="nat-leave-top"><div><div class="nat-leave-name">${esc(x.employee_name)} ${esc(x.employee_title||'')}</div><div class="nat-leave-sub">${esc(x.employee_department||'부서 미지정')} · ${esc(dateText(x.start_date))}${dateText(x.end_date)!==dateText(x.start_date)?' ~ '+esc(dateText(x.end_date)):''}</div></div><span class="nat-pill ${x.leave_type==='statutory'?'STATUTORY':'LEAVE'}">${esc(leaveTypeText(x.leave_type))}</span></div><div class="nat-leave-meta">${Number(x.days||0)}일 · ${esc(leaveStatusText(x.status))} · ${esc(x.reason||'사유 없음')}</div></div>`).join(''):'<div class="nat-empty">휴가 내역이 없습니다.</div>'}</div>`}}
function boot(){let count=0;const timer=setInterval(()=>{ensureStatutoryOption();install();if(document.getElementById('adminOverviewOpen')||++count>80)clearInterval(timer)},200)}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
})();
